extends RefCounted
## Test case: three authored waves escalate by combat problem, not just volume.

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")


func run() -> Dictionary:
	var t := Util.new()
	t.case_name = "three_waves_escalation"
	var h = t.Harness.create(t.load_cfg("mission_default.json"), "balanced")
	t.auto_run(h, func(_p, _w): return "", func(_h): return h.k.final_lull)

	t.eq(h.k.outcome.get("outcome", ""), "SUCCESS", "run concludes")
	t.eq(h.k.waves_completed, 3, "exactly three waves played")

	# Wave 1 teaches: pressure only
	var w1: Array = t.intents_of_wave(h, 1)
	var w1_roles := {}
	for e in w1:
		w1_roles[e.role] = true
	t.ok(w1_roles.has("PRESSURE"), "wave 1 teaches sustained pressure")
	t.ok(not w1_roles.has("ARMORED") and not w1_roles.has("HARASSER"),
		"wave 1 has no new combat problems")

	# Wave 2 complicates: armored + harasser appear
	var w2: Array = t.intents_of_wave(h, 2)
	var w2_roles := {}
	for e in w2:
		w2_roles[e.role] = true
	t.ok(w2_roles.has("ARMORED"), "wave 2 introduces ARMORED")
	t.ok(w2_roles.has("HARASSER"), "wave 2 introduces HARASSER")

	# Wave 3 breaks down: lane C opens + highest unit volume
	var w3: Array = t.intents_of_wave(h, 3)
	var w3_lanes := {}
	var units := [0, 0, 0]
	for e in w1:
		units[0] += int(e.count)
	for e in w2:
		units[1] += int(e.count)
	for e in w3:
		units[2] += int(e.count)
		w3_lanes[e.lane] = true
	t.ok(w3_lanes.has("C"), "wave 3 activates escalation lane C")
	t.ok(units[2] > units[1], "density still escalates (%s)" % str(units))
	return t.result()

extends RefCounted
## Minimal assert-based test utilities. No frameworks.

const Config := preload("res://mission/mission_config.gd")
const Harness := preload("res://tests/orchestrators/kernel/sim_harness.gd")
const Defs := preload("res://mission/defs.gd")

var case_name: String = "unnamed"
var checks: int = 0
var failures: Array = []


func ok(cond: bool, label: String) -> void:
	checks += 1
	if not cond:
		failures.append(label)


func eq(actual, expected, label: String) -> void:
	ok(actual == expected, "%s (got=%s want=%s)" % [label, str(actual), str(expected)])


func result() -> Dictionary:
	return {
		"name": case_name,
		"pass": failures.is_empty(),
		"checks": checks,
		"failures": failures,
	}


func load_cfg(file: String) -> Dictionary:
	var cfg := Config.load_json("res://data/missions/" + file)
	ok(not cfg.is_empty(), "config %s loads" % file)
	ok(Config.validate(cfg).is_empty(), "config %s valid" % file)
	return cfg


## Drive the operation until it concludes, following a simple scripted policy:
## risk_for_phase Callable(phase, waves_completed) -> risk mode or "" (keep).
## Withdraws as soon as allowed AND want_withdrawal says so.
func auto_run(h, risk_for_phase: Callable, want_withdrawal: Callable,
		max_steps: int = 80000) -> void:
	var guard := 0
	while h.k.phase != Defs.CONCLUDED and guard < max_steps:
		guard += 1
		if h.k.phase == Defs.SCOUT:
			var r0: String = risk_for_phase.call(Defs.SCOUT, 0)
			if r0 != "":
				h.k.cmd(Defs.CMD_SET_RISK, {"mode": r0})
			h.k.cmd(Defs.CMD_START_WAVE)
		elif h.k.phase == Defs.INTERMISSION:
			var r: String = risk_for_phase.call(Defs.INTERMISSION, h.k.waves_completed)
			if r != "":
				h.k.cmd(Defs.CMD_SET_RISK, {"mode": r})
			var wr: Dictionary = {"accepted": false}
			if bool(want_withdrawal.call(h)):
				wr = h.k.cmd(Defs.CMD_REQUEST_WITHDRAWAL)
			if not wr.accepted:
				h.k.cmd(Defs.CMD_START_WAVE)
		elif h.k.phase == Defs.ASSAULT and bool(want_withdrawal.call(h)):
			h.k.cmd(Defs.CMD_REQUEST_WITHDRAWAL)
		h.advance(h.step_sec)


func count_intents_by_role(h, role: String, wave_index: int) -> int:
	var n := 0
	for e in h.k.telemetry.events:
		if e.kind == Defs.EV_SPAWN_INTENT and e.get("role", "") == role \
				and String(e.batch_id).begins_with("W%d" % wave_index):
			n += 1
	return n


func intents_of_wave(h, wave_index: int) -> Array:
	return h.k.telemetry.events.filter(func(e):
		return e.kind == Defs.EV_SPAWN_INTENT and String(e.batch_id).begins_with("W%d-" % wave_index))

extends SceneTree

const DT := 1.0 / 60.0


func _initialize() -> void:
	_run()


func _run() -> void:
	await process_frame
	# --- characters.fbx: skeleton? animations?
	var ps: PackedScene = load("res://assets/synty/characters.fbx")
	var inst := ps.instantiate()
	_dump(inst, 0)
	inst.free()

	# --- point-blank rocket crash repro: mech vs big armored, 3 m apart.
	var world := Node3D.new()
	root.add_child(world)
	var kit := SimKit.assemble(world)
	var info: Dictionary = kit.info
	var mech: MechController = kit.mech
	mech.global_position = Vector3(0, 0, 6)
	mech.rotation = Vector3.ZERO
	mech.yaw = PI
	mech.rotation.y = PI
	var big := DummyEnemy.make(world, Vector3(0, 0, 10), "armored", info.core)
	big.speed = 0.0
	var eye: Vector3 = mech.aim_eye()
	var aim := {"from": eye,
			"dir": ((big.global_position + Vector3.UP * 1.2) - eye).normalized()}
	var salvos := 0
	var f := 0
	while is_instance_valid(big) and big.health.hp > 0.0 and f < 60 * 40:
		var fire_s := false
		if mech.weapons.rockets_ready():
			fire_s = true
			salvos += 1
		mech.apply_command(ActorIface.make_command(Vector2.ZERO, Vector2.ZERO,
				false, salvos > 0, fire_s), DT)
		await physics_frame
		f += 1
	print("PB_ROCKET big_hp=%s salvos=%d frames=%d" % [
			str(int(big.health.hp)) if is_instance_valid(big) else 0, salvos, f])
	print("PB_ROCKET mech_hp=%d" % int(mech.health.hp))
	quit(0)


func _dump(n: Node, d: int) -> void:
	var extra := ""
	if n is AnimationPlayer:
		extra = " anims=%s" % str((n as AnimationPlayer).get_animation_list())
	if n is Skeleton3D:
		extra = " bones=%d" % (n as Skeleton3D).get_bone_count()
	if n is MeshInstance3D:
		extra = " skin=%s" % str((n as MeshInstance3D).skin != null)
	print("  ".repeat(d + 1), n.name, " (", n.get_class(), ")", extra)
	for c in n.get_children():
		_dump(c, d + 1)

extends SceneTree

const Util := preload("res://tests/orchestrators/kernel/test_util.gd")
const Defs := preload("res://mission/defs.gd")


func _initialize() -> void:
	var results: Array = []
	results.append(_run_case("conservative_full", "balanced", "SAFE", "full"))
	results.append(_run_case("greedy_early", "balanced", "GREEDY", "early"))
	results.append(_run_case("mixed_full", "balanced", "MIXED", "full"))
	results.append(_run_case("weak_defense", "turretless", "SAFE", "full"))
	results.append(_run_case("mech_overuse_proxy", "core_camp", "GREEDY", "full"))

	var by_name := {}
	for r in results:
		by_name[r.name] = r
	var failures: Array[String] = []
	for r in results:
		if str(r.outcome) == "":
			failures.append("%s did not conclude" % r.name)
	var safe_ready := int(by_name.conservative_full.contract_ready_step)
	var greedy_ready := int(by_name.greedy_early.contract_ready_step)
	if safe_ready <= 0 or greedy_ready <= 0 or greedy_ready >= safe_ready:
		failures.append("GREEDY must reach contract-ready before SAFE")
	if int(by_name.weak_defense.core_hp) > int(by_name.conservative_full.core_hp):
		failures.append("weak defense should not outperform balanced defense on Core HP")

	DirAccess.make_dir_recursive_absolute("res://results")
	var f := FileAccess.open("res://results/operation_strategy_matrix.json", FileAccess.WRITE)
	if f != null:
		f.store_string(JSON.stringify({
			"godot":Engine.get_version_info().string,"results":results,"failures":failures}, "\t", true))
		f.close()
	for r in results:
		print("[STRATEGY] %s outcome=%s waves=%d core=%d ex=%d ready=%d end=%d" % [
			r.name,r.outcome,r.waves_completed,r.core_hp,r.ex_mex,
			r.contract_ready_step,r.duration_steps])
	for failure in failures:
		print("[FAIL] ", failure)
	quit(1 if not failures.is_empty() else 0)


func _run_case(name:String, policy:String, risk_mode:String, extraction_mode:String)->Dictionary:
	var t := Util.new()
	var cfg := t.load_cfg("mission_default.json")
	var h: Object = t.Harness.create(cfg, policy)
	var risk_fn := func(_phase:String, waves_completed:int)->String:
		var desired := risk_mode
		if risk_mode == "MIXED":
			desired = "GREEDY" if waves_completed == 1 else "SAFE"
		return "" if h.k.risk_id == desired else desired
	var withdraw_fn := func(_h)->bool:
		if extraction_mode == "early":
			return h.k.quota_met
		return h.k.final_lull
	t.auto_run(h, risk_fn, withdraw_fn)
	var ready: Dictionary = h.k.telemetry.last_of_kind(Defs.EV_CONTRACT_READY)
	return {
		"name":name,"policy":policy,"risk":risk_mode,
		"outcome":str(h.k.outcome.get("outcome","")),
		"reason":str(h.k.outcome.get("reason","")),
		"waves_completed":h.k.waves_completed,"core_hp":h.k.core_hp,
		"ex_mex":h.k.ex_mex,"contract_ready_step":int(ready.get("step",-1)),
		"duration_steps":h.k.step,"kpis":h.k.kpis(),
	}

## HARVEST crowd lab benchmark runner (headless).
##
## Run from repo root:
##   godot --headless --path labs/crowd --import
##   godot --headless --path labs/crowd --script res://tests/orchestrators/run_benchmarks.gd
## Modes (user args after "--"):
##   (none)              full ladder + isolated benches -> results/
##   single=192          one quick run, prints stats
##   record=150          snapshot recording for scenes/playback.tscn
extends SceneTree

const LADDER := [32, 64, 96, 128, 150, 192, 256, 384, 512]
const SEED := 1337
const DT := 1.0 / 60.0
const WARMUP_TICKS := 120
const MEASURE_TICKS := 900
const SNAP_HZ := 15.0


func _initialize() -> void:
	var mode := "ladder"
	var arg_val := 0
	for a in OS.get_cmdline_user_args():
		if a.begins_with("single="):
			mode = "single"
			arg_val = int(a.get_slice("=", 1))
		elif a.begins_with("record="):
			mode = "record"
			arg_val = int(a.get_slice("=", 1))
	match mode:
		"single":
			_run_single(arg_val)
			quit(0)
		"record":
			_run_record(arg_val)
			quit(0)
		_:
			_run_ladder()
			quit(0)


func _engine_str() -> String:
	var vi := Engine.get_version_info()
	return "%d.%d.%d-%s.%s" % [vi.major, vi.minor, vi.patch, vi.status, vi.build]


func _git_sha() -> String:
	var out := []
	if OS.execute("git", ["rev-parse", "--short", "HEAD"], out) == 0:
		return String(out[0]).strip_edges()
	return "unknown"


func _pctl(sorted_arr: PackedInt64Array, p: float) -> float:
	if sorted_arr.size() == 0:
		return 0.0
	return float(sorted_arr[mini(int(sorted_arr.size() * p), sorted_arr.size() - 1)])


func _stats(us: PackedInt64Array) -> Dictionary:
	var srt := PackedInt64Array(us)
	srt.sort()
	var sum := 0
	for v in us:
		sum += v
	var n := us.size()
	return {
		"mean": float(sum) / maxf(float(n), 1.0),
		"p50": _pctl(srt, 0.50),
		"p95": _pctl(srt, 0.95),
		"p99": _pctl(srt, 0.99),
		"max": float(srt[srt.size() - 1]) if srt.size() > 0 else 0.0,
	}


func _run_one(count: int) -> Dictionary:
	var sim := CrowdSim.new(count, SEED)
	var ren := preload("res://crowd/crowd_renderer.gd").new()
	root.add_child(ren)
	ren.setup(sim, false)
	sim.begin_wave(count, 8.0)
	for t in range(WARMUP_TICKS):
		sim.step(DT)
	ren.sync()
	# drop warmup from stage-stat accumulators so per-frame costs are exact
	sim.take_stats()
	ren.take_sync_us()
	# measurement window
	var frames_us := PackedInt64Array()
	frames_us.resize(MEASURE_TICKS)
	for t in range(MEASURE_TICKS):
		var t0 := Time.get_ticks_usec()
		sim.step(DT)
		var t1 := Time.get_ticks_usec()
		ren.sync()
		var t2 := Time.get_ticks_usec()
		frames_us[t] = (t1 - t0) + (t2 - t1)
	var st := sim.take_stats()
	st["us_render"] = ren.take_sync_us()
	var f := _stats(frames_us)
	var spikes := 0
	for v in frames_us:
		if v > 8000:
			spikes += 1
	root.remove_child(ren)
	ren.free()
	return {
		"count": count, "frames": f,
		"us_agents_per_frame": float(st["us_agents"]) / MEASURE_TICKS,
		"us_hash_per_frame": float(st["us_hash"]) / MEASURE_TICKS,
		"us_spawn_per_frame": float(st["us_spawn"]) / MEASURE_TICKS,
		"us_flow_per_frame": float(st["us_flow"]) / MEASURE_TICKS,
		"us_render_per_frame": float(st["us_render"]) / MEASURE_TICKS,
		"active_end": st["active"],
		"spikes_over_8ms_pct": 100.0 * spikes / MEASURE_TICKS,
		"mem_bytes": sim.memory_bytes(),
	}


func _run_ladder() -> void:
	print("HARVEST crowd ladder | engine ", _engine_str(), " | seed ", SEED,
		" | warmup ", WARMUP_TICKS, "t x measure ", MEASURE_TICKS, "t @60Hz fixed")
	var rows: Array[Dictionary] = []
	for c in LADDER:
		print("  ... running n=%d" % c)
		var r := _run_one(c)
		rows.append(r)
		print(("n=%3d  mean=%.2fms p50=%.2f p95=%.2f p99=%.2f max=%.2f  spike>8ms=%.1f%%  "
			+ "agents=%.0fus hash=%.0fus spawn=%.0fus render=%.0fus")
			% [c, r["frames"]["mean"] / 1000.0, r["frames"]["p50"] / 1000.0,
			r["frames"]["p95"] / 1000.0, r["frames"]["p99"] / 1000.0,
			r["frames"]["max"] / 1000.0, r["spikes_over_8ms_pct"],
			r["us_agents_per_frame"], r["us_hash_per_frame"],
			r["us_spawn_per_frame"], r["us_render_per_frame"]])

	# --- isolated: flow field rebuild ---
	var scratch := CrowdSim.new(32, SEED)
	var rb_us := PackedInt64Array()
	rb_us.resize(60)
	for i in range(60):
		# flip two blockers so every rebuild does real wavefront work
		scratch.set_runtime_blocker(scratch.core_pos.x - 6.0, scratch.core_pos.y, i % 2 == 0)
		rb_us[i] = int(scratch.rebuild_field() * 1000.0)
	var rb := _stats(rb_us)
	print("flow rebuild 80x80: mean=%.3fms p95=%.3f max=%.3f"
		% [rb["mean"] / 1000.0, rb["p95"] / 1000.0, rb["max"] / 1000.0])

	# --- isolated: separation kernel ---
	for c in [128, 256, 512]:
		var sep_ms := _bench_separation(c)
		print("separation-only kernel n=%d: %.3f ms/call (%.1f us)" % [c, sep_ms, sep_ms * 1000.0])

	# --- codec ---
	print("snapshot codec:")
	var codec_rows: Array[Dictionary] = []
	for c in [64, 128, 150, 256]:
		var cr := _bench_codec(c)
		codec_rows.append(cr)
		print("  n=%3d  %5d B/snapshot (%.1f B/enemy)  encode=%.1fus decode=%.1fus  => %.1f KB/s @15Hz"
			% [c, cr["bytes"], cr["bytes_per_enemy"], cr["encode_us"], cr["decode_us"],
			cr["bytes"] * 15.0 / 1024.0])

	_write_results(rows, rb, codec_rows)


func _bench_separation(count: int) -> float:
	var sim := CrowdSim.new(count, SEED)
	sim.begin_wave(count, 0.01)
	while sim.pending_spawn > 0:
		sim.step(DT)
	# park everyone near the core for worst-case density
	for i in range(sim.active):
		sim.px[i] = sim.core_pos.x + randf_range(-3, 3)
		sim.pz[i] = sim.core_pos.y + randf_range(-3, 3)
	var inv := 1.0 / CrowdSim.HASH_CELL
	const SEP_R2 := CrowdSim.SEP_R2
	var reps := 200
	var t0 := Time.get_ticks_usec()
	for r in range(reps):
		sim._rebuild_hash()
		var acc_x := 0.0
		var acc_z := 0.0
		for i in range(sim.active):
			var x := sim.px[i]
			var z := sim.pz[i]
			var bx := clampi(int(x * inv), 0, sim._hw - 1)
			var bz := clampi(int(z * inv), 0, sim._hh - 1)
			for yy in range(maxi(bz - 1, 0), mini(bz + 1, sim._hh - 1) + 1):
				var rowb := yy * sim._hw
				for xx in range(maxi(bx - 1, 0), mini(bx + 1, sim._hw - 1) + 1):
					var b := rowb + xx
					for k in range(sim._hstarts[b], sim._hstarts[b + 1]):
						var j: int = sim._horder[k]
						if j == i:
							continue
						var dx := x - sim.px[j]
						var dz := z - sim.pz[j]
						var d2 := dx * dx + dz * dz
						if d2 < SEP_R2 and d2 > 0.000001:
							var w := (SEP_R2 - d2) / SEP_R2 / sqrt(d2)
							acc_x += dx * w
							acc_z += dz * w
	var dt_us := float(Time.get_ticks_usec() - t0) / reps
	return dt_us / 1000.0


func _bench_codec(count: int) -> Dictionary:
	var sim := CrowdSim.new(count, SEED)
	sim.begin_wave(count, 0.01)
	while sim.pending_spawn > 0:
		sim.step(DT)
	EnemySnapshotCodec.clear_events(sim)
	var reps := 300
	var bytes_out := PackedByteArray()
	var dec := {}
	var te := PackedInt64Array()
	te.resize(reps)
	var td := PackedInt64Array()
	td.resize(reps)
	for r in range(reps):
		var t0 := Time.get_ticks_usec()
		bytes_out = EnemySnapshotCodec.encode(sim, r)
		te[r] = Time.get_ticks_usec() - t0
		t0 = Time.get_ticks_usec()
		dec = EnemySnapshotCodec.decode(bytes_out)
		td[r] = Time.get_ticks_usec() - t0
	var se := _stats(te)
	var sd := _stats(td)
	return {
		"bytes": bytes_out.size(),
		"bytes_per_enemy": float(bytes_out.size()) / maxf(float(dec["uid"].size()), 1.0),
		"encode_us": se["p50"], "decode_us": sd["p50"],
		"encode_p99": se["p99"], "decode_p99": sd["p99"],
	}


func _run_record(count: int) -> void:
	var sim := CrowdSim.new(count, SEED)
	sim.begin_wave(count, 10.0)
	var path := "res://results/recording_%d.bin" % count
	var f := FileAccess.open(path, FileAccess.WRITE)
	var meta := {
		"seed": SEED, "count": count, "hz": SNAP_HZ, "dt": DT,
		"arena_m": FlowField.DEFAULT_CELL * FlowField.DEFAULT_W, "engine": _engine_str(),
	}
	f.store_buffer(PackedByteArray())   # placeholder, real snapshots below
	var snaps: Array[PackedByteArray] = []
	var acc := 0.0
	var tick_times := PackedFloat64Array()
	for t in range(1200):
		sim.step(DT)
		acc += DT
		if acc >= 1.0 / SNAP_HZ - 0.00001:
			snaps.append(EnemySnapshotCodec.encode(sim, t))
			tick_times.append(t * DT)
			acc -= 1.0 / SNAP_HZ
	var max_b := 0
	for s in snaps:
		max_b = maxi(max_b, s.size())
	meta["snapshot_bytes_max"] = max_b
	meta["snapshots"] = snaps.size()
	f.store_32(snaps.size())
	for s in snaps:
		f.store_32(s.size())
		f.store_buffer(s)
	f.close()
	var fm := FileAccess.open(path.replace(".bin", ".json"), FileAccess.WRITE)
	fm.store_string(JSON.stringify(meta, "  "))
	fm.close()
	print("recording written: %s (%d snapshots, %d B each)"
		% [path, meta["snapshots"], meta["snapshot_bytes"]])


func _run_single(count: int) -> void:
	var r := _run_one(count)
	print("n=%d mean=%.2fms p99=%.2f max=%.2f active=%d"
		% [count, r["frames"]["mean"] / 1000.0, r["frames"]["p99"] / 1000.0,
		r["frames"]["max"] / 1000.0, r["active_end"]])


func _write_results(rows: Array[Dictionary], rb: Dictionary, codec_rows: Array[Dictionary]) -> void:
	var ts := Time.get_datetime_string_from_system(true).replace(":", "").replace("-", "")
	DirAccess.make_dir_recursive_absolute("res://results")
	var csv := "ts,engine,count,sim_ms_mean,sim_ms_p50,sim_ms_p95,sim_ms_p99,sim_ms_max," \
		+ "spikes_over_8ms_pct,us_agents,us_hash,us_spawn,us_flow,us_render,active_end,mem_bytes\n"
	for r in rows:
		csv += "%s,%s,%d,%.3f,%.3f,%.3f,%.3f,%.3f,%.2f,%.1f,%.1f,%.1f,%.1f,%.1f,%d,%d\n" \
			% [ts, _engine_str(), r["count"], r["frames"]["mean"] / 1000.0,
			r["frames"]["p50"] / 1000.0, r["frames"]["p95"] / 1000.0,
			r["frames"]["p99"] / 1000.0, r["frames"]["max"] / 1000.0,
			r["spikes_over_8ms_pct"], r["us_agents_per_frame"], r["us_hash_per_frame"],
			r["us_spawn_per_frame"], r["us_flow_per_frame"], r["us_render_per_frame"],
			r["active_end"], r["mem_bytes"]]
	var fc := FileAccess.open("res://results/bench_ladder.csv", FileAccess.WRITE)
	fc.store_string(csv)
	fc.close()
	var doc := {
		"timestamp": ts, "seed": SEED, "dt": DT,
