## HSNP v1 codec + interpolation sampler tests (VS2-T2/T3/T5).
## Run: godot --path labs/netcode --headless -s tests/test_hsnp.gd

var fails := 0
var fail_flag := false
var _frames := 0


func _process(_delta: float) -> bool:
	_frames += 1
	if _frames > 600:   # watchdog: never hang the harness
		return true
	return fail_flag


func check(cond: bool, msg: String) -> void:
	if not cond:
		fails += 1
		fail_flag = true
		print("FAIL ", msg)


func _mk(n: int) -> Dictionary:
	var uid := PackedInt32Array(); uid.resize(n)
	var x := PackedFloat32Array(); x.resize(n)
	var z := PackedFloat32Array(); z.resize(n)
	var hp := PackedFloat32Array(); hp.resize(n)
	var st := PackedInt32Array(); st.resize(n)
	var fl := PackedInt32Array(); fl.resize(n)
	var ln := PackedInt32Array(); ln.resize(n)
	for i in n:
		uid[i] = 1000 + i * 7          # non-contiguous uids
		x[i] = randf() * 48.0          # HSNP domain: [0, arena_size_m]
		z[i] = randf() * 48.0
		hp[i] = float((i * 13) % 101)
		st[i] = i % 3                  # includes 2=dead per canon
		fl[i] = 0
		ln[i] = i % 4
	return {
		"tick": 4242, "arena_size_m": 48.0,
		"uid": uid, "x": x, "z": z, "hp": hp, "state": st, "flags": fl, "lane": ln,
		"spawned": PackedInt32Array([1007, 1021]),
		"died": PackedInt32Array([1014]),
	}


func _init() -> void:
	seed(1234)

	# --- roundtrip with uid identity ---
	var p := _mk(64)
	var bytes := EnemySnapshotCodec.encode_dict(p)
	print("hsnp64_size=", bytes.size(), " expected=", 16 + 64 * 11 + 6 + 4)
	check(bytes.size() == 16 + 64 * 11 + 6 + 4, "wire size")
	var d := EnemySnapshotCodec.decode(bytes)
	check(not d.is_empty(), "decode ok")
	check(d.tick == 4242 and d.arena_size_m == 48.0, "header fields")
	for i in 64:
		if d.uid[i] != p.uid[i]:
			check(false, "uid identity broken at %d" % i)
			break
	check(d.uid[5] == p.uid[5] and d.uid[63] == p.uid[63], "uid spot checks")
	for i in [0, 17, 63]:
		check(absf(d.x[i] - p.x[i]) < 0.01, "x quantization @%d" % i)
		check(absf(d.z[i] - p.z[i]) < 0.01, "z quantization @%d" % i)
		check(absf(d.hp[i] - p.hp[i]) < 0.01, "hp quantization @%d" % i)
		check(d.state[i] == p.state[i], "state @%d (2=dead preserved)" % i)
	check(d.spawned.size() == 2 and d.spawned[1] == 1021, "spawned events")
	check(d.died.size() == 1 and d.died[0] == 1014, "died events")

	# --- UID32 death event regression ---
	var sim32 := CrowdSim.new(2, 55)
	sim32._next_uid = 70000
	sim32.begin_wave(1, 0.01)
	for i in 4:
		sim32.step(1.0 / 60.0)
	var uid32 := sim32.uid[0]
	sim32.damage(uid32, 9999.0)
	var bytes32 := EnemySnapshotCodec.encode(sim32, 7, true)
	var decoded32 := EnemySnapshotCodec.decode(bytes32)
	check(decoded32.died.size() == 1 and decoded32.died[0] == uid32,
		"uid32 death event preserves full uid")

	# --- hard-fail paths ---
	var bad_magic := bytes.duplicate()
	bad_magic[0] = 0x00
	check(EnemySnapshotCodec.decode(bad_magic).is_empty(), "bad magic rejected")
	var bad_ver := bytes.duplicate()
	bad_ver[4] = 0x09
	bad_ver[5] = 0x99
	check(EnemySnapshotCodec.decode(bad_ver).is_empty(), "bad version rejected")
	check(EnemySnapshotCodec.decode(PackedByteArray([1, 2, 3])).is_empty(), "truncated rejected")

	# --- hostile count clamp (VS2-T2) ---
	var hostile := StreamPeerBuffer.new()
	hostile.put_u32(EnemySnapshotCodec.MAGIC)
	hostile.put_u16(EnemySnapshotCodec.VERSION)
	hostile.put_u32(1)
	hostile.put_float(48.0)
	hostile.put_u16(60000)   # claims 60000 enemies on a tiny packet
	check(EnemySnapshotCodec.decode(hostile.data_array).is_empty(), "hostile count clamped")

	# --- interp sampler (VS2-T3) ---
	var n := 8
	var uid8 := PackedInt32Array(); uid8.resize(n)
	var ax := PackedFloat32Array(); ax.resize(n)
	var az := PackedFloat32Array(); az.resize(n)
	var st8 := PackedByteArray(); st8.resize(n)
	for i in n:
		uid8[i] = i
		ax[i] = float(i)
		az[i] = float(i) * 2.0
		st8[i] = 2 if i == 1 else 0     # one dead enemy
	var a := {"recv_ms": 1000, "uid": uid8, "x": ax, "z": az, "state": st8, "hp": p.hp}
	var bx := PackedFloat32Array(); bx.resize(n)
	var bz := PackedFloat32Array(); bz.resize(n)
	for i in n:
		bx[i] = ax[i] + 2.0
		bz[i] = az[i] + 4.0
	var b := {"recv_ms": 1100, "uid": uid8, "x": bx, "z": bz, "state": st8, "hp": p.hp}

	var s := CrowdInterp.sample_interp(a, b, 1150, 100.0)
	check(not s.is_empty(), "interp mid-window")
	check(absf(s.x[3] - (ax[3] + 1.0)) < 0.001, "midpoint lerp x")
	check(absf(s.z[3] - (az[3] + 2.0)) < 0.001, "midpoint lerp z")
	check(s.state[1] == 2, "dead state carried through")

	var s0 := CrowdInterp.sample_interp(a, b, 900, 100.0)     # target before buffer
	check(not s0.is_empty() and absf(s0.x[3] - ax[3]) < 0.001, "pre-buffer clamps to oldest snap")

	var s1 := CrowdInterp.sample_interp(a, b, 1300, 100.0)    # target past newest
	check(not s1.is_empty() and absf(s1.x[3] - bx[3]) < 0.001, "post-buffer clamps to newest")

	var bad := a.duplicate()
	bad.uid = PackedInt32Array()
	check(CrowdInterp.sample_interp(bad, b, 1050, 100.0).is_empty(), "size mismatch rejected")

	print("HSNP_TEST_%s" % ("OK" if fails == 0 else "FAILED"))
	quit(1 if fails > 0 else 0)

class_name SmokeLib
extends RefCounted

## Zero-dependency smoke harness (VS-1). Discovers root res://tests/test_*.gd
## SmokeTestBase suites only; tests/orchestrators/** use dedicated runners.
## calls every test_* method, returns the process exit code:
##   0 pass | 1 failures | 2 misconfiguration
## A suite that fails to load, or a method that runs zero assertions
## (e.g. aborted by a script error), counts as failed.
## Entry points: tests/run_smoke.gd (-s shim) and boot.gd TEST branch.


static func run_all() -> int:
	var files: PackedStringArray = []
	_collect("res://tests", files)
	files.sort()
	if files.is_empty():
		printerr("SMOKE MISCONFIG: no test_*.gd found under res://tests")
		return 2

	var failed_methods := 0
	for path in files:
		print("== %s" % path)
		var script: GDScript = load(path)
		if script == null or not script.can_instantiate():
			printerr("  FAIL <suite load failed>")
			failed_methods += 1
			continue
		var suite: SmokeTestBase = script.new()
		for m in suite.get_method_list():
			var method_name := String(m["name"])
			if not method_name.begins_with("test_"):
				continue
			var before_checks := suite.checks
			var before_failures := suite.failures
			suite.call(method_name)
			if suite.checks == before_checks:
				printerr("  FAIL %s (no checks executed)" % method_name)
				failed_methods += 1
			elif suite.failures > before_failures:
				printerr("  FAIL %s" % method_name)
				failed_methods += 1
			else:
				print("  PASS %s" % method_name)

	print("-- %d suite(s) run: %d failed test(s)" % [files.size(), failed_methods])
	return 1 if failed_methods > 0 else 0


static func _collect(dir_path: String, out: PackedStringArray) -> void:
	var dir := DirAccess.open(dir_path)
	if dir == null:
		return
	dir.list_dir_begin()
	var entry := dir.get_next()
	while entry != "":
		if not dir.current_is_dir() and entry.begins_with("test_") and entry.ends_with(".gd"):
			out.append(dir_path.path_join(entry))
		entry = dir.get_next()
	dir.list_dir_end()

